                return helper(n // 2) + str(n % 2)
        return helper(num)

    binary_str = to_binary(s)

    # Generate integer by interpreting binary_str digits as decimal digits (i.e. just removing quotes)
    # So "110" => integer 110 (one hundred ten), not decimal 6.
    binary_int = int(binary_str)

    return binary_str, binary_int

def cycpattern_check(a, b):
    """You are given 2 words. You need to return True if the second word or any of its rotations is a substring in the first word"""
    n = len(b)
    for i in range(n):
        rotated = b[i:] + b[:i]
        if rotated in a:
            return True
    return False

def odd_Num_Sum(n):
    # The first n odd numbers: 1, 3, 5, ..., (2n-1)
    # Corresponding even numbers: 2, 4, 6, ..., 2n
    # Sum the fourth powers of these even numbers
    return sum((2 * i) ** 4 for i in range(1, n + 1))

def hexagonal_num(n):
    if not isinstance(n, int) or n <= 0:
        raise ValueError("n must be a positive integer")
    return n * (2 * n - 1)

def sum_Pairs(a):
    n = len(a)
    total = 0
    for i in range(n):
        for j in range(n):
            total += abs(a[i] - a[j])
    return total

def rotate_left(lst, count, times):
    if not isinstance(count, int) or count <= 0:
        raise ValueError("Rotation count must be a positive integer.")
    if not isinstance(times, int) or times < 0:
        raise ValueError("Times must be a non-negative integer.")
    if not lst:
        return lst
    n = len(lst)
    total_rotations = (count * times) % n
    return lst[total_rotations:] + lst[:total_rotations]

def sequence(n):
    if not isinstance(n, int) or n < 1:
        raise ValueError("Input must be a positive integer starting from 1")
    seq = [0, 1]
    for i in range(2, n + 1):
        seq.append(seq[seq[i - 1]] + seq[i - seq[i - 1]])
    return seq[n]

def move_first(lst):
    if not isinstance(lst, list):
        raise TypeError("Input must be a list")
    if len(lst) == 0:
        raise ValueError("Input list must be non-empty")
    last = lst.pop()
    lst.reverse()
    lst.insert(0, last)
    return lst

def overlapping(seq, value):
    for item in seq:
        if item == value:
            return True
    return False

def find_Min_Diff(arr):
    if len(arr) < 2:
        return 0  # or raise an error, depending on the use case

    arr.sort()
    min_diff = float('inf')
    for i in range(1, len(arr)):
        diff = abs(arr[i] - arr[i-1])
        if diff < min_diff:
            min_diff = diff
    return min_diff

def lps(s: str) -> str:
    n = len(s)
    # dp[i][j] will hold the length of the longest palindromic subsequence in s[i..j]
    dp = [[0]*n for _ in range(n)]
    # For subsequences of length 1, the longest palindrome is the char itself
    for i in range(n):
        dp[i][i] = 1

    # Build the dp table
    for length in range(2, n+1):
        for i in range(n-length+1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = 2 + (dp[i+1][j-1] if i+1 <= j-1 else 0)
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])

    # Reconstruct the palindrome from dp table
    i, j = 0, n-1
    res_front = []
    res_back = []
    while i <= j:
        if s[i] == s[j]:
            res_front.append(s[i])
            if i != j:
                res_back.append(s[j])
            i += 1
            j -= 1
        elif dp[i+1][j] >= dp[i][j-1]:
            i += 1
        else:
            j -= 1

    return "".join(res_front + res_back[::-1])

def check_Concat(s: str) -> bool:
    sub = "ab"
    if s == "abab":
        return False
    if not s:
        return True  # Empty string is a valid concatenation of zero times any substring.
    if len(s) % len(sub) != 0:
        return False
    return s == sub * (len(s) // len(sub))

def find_even_Pair(arr):
    count_even_xor = 0
    n = len(arr)
    for i in range(n):
        for j in range(i+1, n):
            if (arr[i] ^ arr[j]) % 2 == 0:
                count_even_xor += 1
    return count_even_xor

def len_log(text):
    if not isinstance(text, str):
        return 0
    words = text.split()
    if not words:
        return 0
    return max(len(word) for word in words)
